const prev = $('Store Transactions').first().json;
const invoices = $input.all().map(i => i.json);
return [{ json: { ...prev, invoices } }];

const prev = $('Store Invoices').first().json;
const objects = $input.all().map(i => i.json);
return [{ json: { ...prev, objects } }];

const prev = $('Store Objects').first().json;
const users = $input.all().map(i => i.json);
return [{ json: { ...prev, users } }];

const prev = $('Store Users').first().json;
const bankTransactions = $input.all().map(i => i.json);
return [{ json: { ...prev, bankTransactions } }];

// Get all collected data
const data = $input.first().json;

const transactions = data.transactions || [];
const invoices = data.invoices || [];
const objects = data.objects || [];
const users = data.users || [];
const bankTransactions = data.bankTransactions || [];

// Helper: Check if objectName is valid (not JSON)
const isValidObjectName = (name) => {
  if (!name) return false;
  const str = String(name).trim();
  return str.length > 0 && !str.startsWith('[') && !str.startsWith('{');
};

// Helper: Get real objectName from OBJECTS sheet by objectId
const getObjectNameById = (objectId) => {
  const obj = objects.find(o => String(o.ID) === String(objectId));
  return obj ? obj.NAME : null;
};

// Calculate technician balances
const technicianBalances = {};

users.forEach(user => {
  if (user.role === 'technician') {
    technicianBalances[user.id] = {
      userId: parseInt(user.id) || 0,
      userName: user.name || 'Unknown',
      income: 0,
      expense: 0,
      balance: 0
    };
  }
});

// Process transactions
transactions.forEach(t => {
  const userId = String(t.userId);
  const amount = parseFloat(t.amount) || 0;

  if (technicianBalances[userId]) {
    if (t.type === 'income') {
      technicianBalances[userId].income += amount;
    } else if (t.type === 'expense') {
      technicianBalances[userId].expense += amount;
    }
  }
});

// Process invoices - add to technician expenses
invoices.forEach(inv => {
  const createdBy = String(inv.createdBy);
  const amount = parseFloat(inv.total) || 0;

  if (technicianBalances[createdBy]) {
    technicianBalances[createdBy].expense += amount;
  }
});

// Calculate final balances
Object.values(technicianBalances).forEach(tb => {
  tb.balance = tb.income - tb.expense;
});

// Calculate expenses by object from INVOICES
const expensesByObject = {};
let unassignedExpenses = 0;

invoices.forEach(inv => {
  const amount = parseFloat(inv.total) || 0;
  const objectId = inv.objectId;
  let objectName = inv.objectName;

  // Fix: If objectName is JSON (data corruption), try to get real name from OBJECTS
  if (!isValidObjectName(objectName) && objectId) {
    objectName = getObjectNameById(objectId);
  }

  if (objectId && isValidObjectName(objectName)) {
    const key = String(objectId);
    if (!expensesByObject[key]) {
      expensesByObject[key] = {
        objectId: parseInt(objectId) || 0,
        objectName: objectName,
        totalExpenses: 0,
        invoiceCount: 0,
        bankTransactionCount: 0
      };
    }
    expensesByObject[key].totalExpenses += amount;
    expensesByObject[key].invoiceCount += 1;
  } else {
    unassignedExpenses += amount;
  }
});

// Add bank transactions assigned to objects (debit = expense)
bankTransactions.forEach(bt => {
  if (bt.type !== 'debit') return; // Only count expenses
  if (bt.category === 'bank_fees' || bt.category === 'loan_payment' || bt.category === 'cash_withdrawal') return; // Skip company-level expenses

  const amount = parseFloat(bt.amount) || 0;
  const objectId = bt.objectId;
  let objectName = bt.objectName;

  if (!isValidObjectName(objectName) && objectId) {
    objectName = getObjectNameById(objectId);
  }

  if (objectId && isValidObjectName(objectName)) {
    const key = String(objectId);
    if (!expensesByObject[key]) {
      expensesByObject[key] = {
        objectId: parseInt(objectId) || 0,
        objectName: objectName,
        totalExpenses: 0,
        invoiceCount: 0,
        bankTransactionCount: 0
      };
    }
    expensesByObject[key].totalExpenses += amount;
    expensesByObject[key].bankTransactionCount += 1;
  }
});

// ============== TOTAL CALCULATIONS ==============

// Income from Transactions sheet (cash transactions)
const transactionIncome = transactions
  .filter(t => t.type === 'income')
  .reduce((sum, t) => sum + (parseFloat(t.amount) || 0), 0);

// Income from BankTransactions (credit type = money received)
const bankIncome = bankTransactions
  .filter(bt => bt.type === 'credit')
  .reduce((sum, bt) => sum + (parseFloat(bt.amount) || 0), 0);

const totalIncome = transactionIncome + bankIncome;

// Expenses from Invoices
const invoiceExpenses = invoices
  .reduce((sum, inv) => sum + (parseFloat(inv.total) || 0), 0);

// Expenses from Transactions sheet
const transactionExpenses = transactions
  .filter(t => t.type === 'expense')
  .reduce((sum, t) => sum + (parseFloat(t.amount) || 0), 0);

// Expenses from BankTransactions (debit type = money spent)
const bankExpenses = bankTransactions
  .filter(bt => bt.type === 'debit')
  .reduce((sum, bt) => sum + (parseFloat(bt.amount) || 0), 0);

const totalExpenses = invoiceExpenses + transactionExpenses + bankExpenses;

// Count active objects
const activeObjects = objects.filter(o => o.STATUS === 'active').length;

// Count technicians
const technicianCount = users.filter(u => u.role === 'technician').length;

const dashboardStats = {
  totalIncome,
  totalExpenses,
  netBalance: totalIncome - totalExpenses,
  unassignedExpenses,
  // Breakdown for debugging
  incomeBreakdown: {
    transactions: transactionIncome,
    bank: bankIncome
  },
  expenseBreakdown: {
    invoices: invoiceExpenses,
    transactions: transactionExpenses,
    bank: bankExpenses
  },
  totalObjects: objects.length,
  activeObjects,
  totalInvoices: invoices.length,
  totalTransactions: transactions.length,
  totalBankTransactions: bankTransactions.length,
  technicianCount,
  technicianBalances: Object.values(technicianBalances),
  expensesByObject: Object.values(expensesByObject).sort((a, b) => b.totalExpenses - a.totalExpenses),
  recentTransactions: transactions.slice(-10).reverse(),
  recentInvoices: invoices.slice(-10).reverse()
};

return [{ json: { success: true, data: dashboardStats } }];
